function C:PlayScenarioToNextSerihu()
  while self.playing.Count > 0 do
    local playing = IDX(self.playing, 0)
    spawn(function() self:Play(IDX(self.playing, 0)) end)
    self.playing:RemoveAt(0)
    if playing.isJimaku then
