function C:Play(context)
  if not coroutine.isyieldable() then spawn(C.Play, self, context) return end
  if context.startReading then
    self._Live:ReadComment()
    self.BASESPEED = 1
    return
  end
  if context.isSetting then
    if context.ongaku ~= "None" then
      AudioManager:PlaySeByType(context.ongaku, context.isLoopAnim)
      return
    end
    ChanceEffectController._current.Value = context.obi
    ChanceEffectController._anim.Value = context.inout
    EventManager:ObiActive(false)
    self.BASESPEED = 1
    return
  end
  if context.isYohaku then
    self.BASESPEED = 1
    self._Live:AddMob(context.nakami)
    self._Live.CommentScroll.verticalNormalizedPosition = 0
    return
  end
  if context.isJimaku then
    self.BASESPEED = self.STARTSPEED
    self:showJimaku(context)
    self._Live:setAnti(context.antiComment, context.showAnti)
    return
  end
  self.BASESPEED = IDIV(self.STARTSPEED, 14) * STR.Length(context.nakami)
  if Settings.CurrentLanguage.Value == "EN" then
    if EventManager.nowEnding == "Ending_Ideon" then
      self.BASESPEED = Mathf.CeilToInt(self.BASESPEED / 2.5)
    elseif EventManager.nowEnding == "Ending_Ginga" then
      self.BASESPEED = Mathf.CeilToInt(self.BASESPEED / 2)
    end
  end
  self:showComment(context)
  UniTask.Yield()
  self._Live.CommentScroll.verticalNormalizedPosition = 0
end

function C:showComment(context)
  self._Live:NewComment(context)
end

function C:showJimaku(context)
  if not coroutine.isyieldable() then spawn(C.showJimaku, self, context) return end
  if context.animation ~= "" then
    self._Live:ChotenAnimation(context.animation, context.isLoopAnim)
  end
  self._Live:ShowJimaku(context)
end

function C:OnDestroy()
